  if (kind == 2) fade = (1.0 - u) * (1.0 - u) * (1.0 - u);
  else if (kind == 3) fade = smoothstep(0.0, 0.12, u) * (1.0 - u) * 0.9;
  else fade = 1.0 - u * u * u;
